const __pageData = JSON.parse('{"title":"Docker自定义镜像与网络","description":"自定义镜像这一篇——先把镜像是什么讲清（应用 + 系统函数库 + 运行配置一起打包），再把镜像结构拆成基础镜像、层、入口三部分；Dockerfile 的六个指令 FROM/ENV/COPY/RUN/EXPOSE/ENTRYPOINT 逐个对号入座，课程那份从 CentOS 7 装 JDK 再拷 jar 的 Dockerfile 逐行读完，接着用本机实测的一份「模拟 Java 应用」镜像把构建、运行、看日志、端口映射整条链路的证据摆出来；最后补上默认 bridge 网桥与自定义网络那一节，说清为什么「只有加入同一个自定义网络的容器才能用容器名互访」","frontmatter":{"title":"Docker自定义镜像与网络","published":"2026-09-29T00:00:00.000Z","description":"自定义镜像这一篇——先把镜像是什么讲清（应用 + 系统函数库 + 运行配置一起打包），再把镜像结构拆成基础镜像、层、入口三部分；Dockerfile 的六个指令 FROM/ENV/COPY/RUN/EXPOSE/ENTRYPOINT 逐个对号入座，课程那份从 CentOS 7 装 JDK 再拷 jar 的 Dockerfile 逐行读完，接着用本机实测的一份「模拟 Java 应用」镜像把构建、运行、看日志、端口映射整条链路的证据摆出来；最后补上默认 bridge 网桥与自定义网络那一节，说清为什么「只有加入同一个自定义网络的容器才能用容器名互访」","tags":["JavaWeb","Docker","部署"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-112-docker-image-network.webp","order":112,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/112-Docker自定义镜像与网络.md","filePath":"posts/学习文档/JavaWeb学习笔记/112-Docker自定义镜像与网络.md"}');
